BEGIN;
SELECT no_plan();
CREATE TEMP TABLE tested_rpcs AS
 SELECT p.oid,p.oid::regprocedure::text signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname ~ '^platform_product_(execution_|closure_)';
SELECT is((SELECT count(*)::integer FROM tested_rpcs),6,'complete execution and closure RPC family');
SELECT ok(NOT has_function_privilege('anon',oid,'EXECUTE'),'anon denied '||signature) FROM tested_rpcs;
SELECT ok(NOT has_function_privilege('authenticated',oid,'EXECUTE'),'user denied '||signature) FROM tested_rpcs;
SELECT ok(has_function_privilege('service_role',oid,'EXECUTE'),'service allowed '||signature) FROM tested_rpcs;
SELECT ok(NOT EXISTS(SELECT FROM tested_rpcs r JOIN pg_proc p ON p.oid=r.oid,LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE'),'no PUBLIC capability');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='grida_platform.product_closure_outbox'::regclass),'closure evidence RLS enabled and forced');
SELECT set_config('test.owner',(SELECT id::text FROM auth.users WHERE email='insider@grida.co'),true);
INSERT INTO public.organization(name,display_name,owner_id) VALUES('shared-credit-proof','Shared credit',current_setting('test.owner')::uuid);
SELECT set_config('test.org',(SELECT id::text FROM public.organization WHERE name='shared-credit-proof'),true);
SELECT set_config('test.claim',jsonb_build_object('organization_id',current_setting('test.org'),'product','grida-ai','operation','image','model','fixture/image','unit','cost_mills','policy_version','shared-ai-v1','request_digest',repeat('a',64),'admission_observed_at',clock_timestamp()::text,'admission_expires_at',(clock_timestamp()+interval '50 seconds')::text,'authorized_mills','10','expense_bound_mills','10','tariff_revision',repeat('b',64))::text,true);
SELECT set_config('test.receipt',jsonb_build_object('organization_id',current_setting('test.org'),'product','grida-ai','operation','image','model','fixture/image','unit','cost_mills','policy_version','shared-ai-v1','outcome','succeeded','quantity','0.000000000000000001','occurred_at',clock_timestamp()::text,'evidence_digest',repeat('c',64))::text,true);
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.platform_product_execution_claim('grida-ai','shared-active',current_setting('test.claim')::jsonb)$$,'42501',NULL,'actual anon claim denied');
SELECT throws_ok($$SELECT public.platform_product_execution_close('grida-ai','shared-never',current_setting('test.claim')::jsonb)$$,'42501',NULL,'actual anon closure denied');
SELECT throws_ok('SELECT public.platform_product_closure_page(100)','42501',NULL,'actual anon page denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.platform_product_execution_claim('grida-ai','shared-active',current_setting('test.claim')::jsonb)$$,'42501',NULL,'actual user claim denied');
SELECT throws_ok($$SELECT public.platform_product_execution_close('grida-ai','shared-never',current_setting('test.claim')::jsonb)$$,'42501',NULL,'actual user closure denied');
SELECT throws_ok($$SELECT public.platform_product_execution_dispatch('grida-ai','shared-active')$$,'42501',NULL,'actual user dispatch denied');
SELECT throws_ok($$SELECT public.platform_product_execution_receipt('grida-ai','shared-active',current_setting('test.receipt')::jsonb)$$,'42501',NULL,'actual user receipt denied');
SELECT throws_ok('SELECT public.platform_product_closure_page(100)','42501',NULL,'actual user page denied');
SELECT throws_ok($$SELECT public.platform_product_closure_ack(ARRAY['50000000-0000-4000-8000-000000000001'::uuid])$$,'42501',NULL,'actual user ack denied');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT is(public.platform_product_execution_claim('grida-ai','shared-active',current_setting('test.claim')::jsonb)->>'created','true','service commits bounded claim');
SELECT is(public.platform_product_execution_dispatch('grida-ai','shared-active')->>'dispatch','true','source dispatch once');
SELECT is(public.platform_product_execution_dispatch('grida-ai','shared-active')->>'dispatch','false','replay never redispatches');
SELECT is(public.platform_product_execution_close('grida-ai','shared-active',current_setting('test.claim')::jsonb)->>'state','dispatched','cannot close possibly billable work');
SELECT is(public.platform_product_execution_receipt('grida-ai','shared-active',current_setting('test.receipt')::jsonb)->>'accepted','true','exact fractional receipt accepted');
SELECT is(public.platform_product_execution_receipt('grida-ai','shared-active',current_setting('test.receipt')::jsonb)->>'duplicate','true','same receipt replays');
SELECT is(public.platform_product_execution_close('grida-ai','shared-never',current_setting('test.claim')::jsonb)->>'state','closed','closure creates source tombstone before delayed claim');
SELECT is(public.platform_product_execution_claim('grida-ai','shared-never',current_setting('test.claim')::jsonb)->>'state','closed','delayed claim cannot reopen closure');
SELECT is(public.platform_product_execution_dispatch('grida-ai','shared-never')->>'dispatch','false','closed work cannot dispatch');
SELECT throws_ok($$SELECT public.platform_product_execution_receipt('grida-ai','shared-never',current_setting('test.receipt')::jsonb)$$,'22023',NULL,'closed work cannot create paid receipt');
SELECT is(jsonb_array_length(public.platform_product_closure_page(100)->'events'),1,'one durable closure event');
SELECT is(public.platform_product_closure_ack(ARRAY[(public.platform_product_closure_page(100)->'events'->0->>'event_id')::uuid])->>'acknowledged','true','service acknowledges original closure');
SELECT is(jsonb_array_length(public.platform_product_closure_page(100)->'events'),0,'acked closure is not redelivered');
SELECT throws_ok($$SELECT public.platform_product_execution_claim('grida-ai','shared-invalid',current_setting('test.claim')::jsonb||'{"expense_bound_mills":"-1"}'::jsonb)$$,'22023',NULL,'negative bound rejected');
SELECT throws_ok($$SELECT public.platform_product_execution_claim('grida-ai','shared-invalid',current_setting('test.claim')::jsonb-'tariff_revision')$$,'22023',NULL,'missing tariff rejected');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM grida_platform.product_closure_outbox),1,'ack retains immutable proof');
SELECT * FROM finish();
ROLLBACK;
